def point_in_hull(hull, pts):
    # hull: kx2 vertices in CCW order (scipy ConvexHull.vertices are CCW for 2D)
    k=len(hull); inside=np.ones(len(pts),bool)
    for i in range(k):
        a=hull[i]; b=hull[(i+1)%k]
        d=b-a
        n=np.array([d[1],-d[0]])  # for CCW polygon, outward normal is (dy,-dx)
        s=(pts-a)@n
        inside &= (s<=1e-9)
    return inside
def hull_rule(A,v,K):
    H,W=A.shape
    pts=[(int(r),int(c)) for r,c in zip(*np.where(A==v))]
    par=list(range(len(pts)))
    def find(i):
        while par[i]!=i: par[i]=par[par[i]]; i=par[i]
        return i
    for i in range(len(pts)):
        for j in range(i):
            if max(abs(pts[i][0]-pts[j][0]),abs(pts[i][1]-pts[j][1]))<=K:
                par[find(i)]=find(j)
    comps={}
    for i in range(len(pts)): comps.setdefault(find(i),[]).append(pts[i])
    fill=np.zeros((H,W),bool)
    gridm=np.array([(r,c) for r in range(H) for c in range(W)],float)
    for g,ps in comps.items():
        if len(ps)<3: continue
        P=np.array(ps,float)
        try: hl=ConvexHull(P)
        except Exception: continue
        hull=P[hl.vertices]
        fill|=point_in_hull(hull,gridm).reshape(H,W)
    return fill
